const input = $('Webhook').first().json;

// Handle different payload formats
let parsedData;

if (typeof input.body === "string") {
  try {
    parsedData = JSON.parse(input.body);
  } catch (e) {
    parsedData = input.body;
  }
} else if (input.body && typeof input.body === "object") {
  parsedData = input.body;
} else {
  parsedData = input;
}

// Helper: strip a stray leading "=" the Poller sometimes sends (unevaluated expression)
const clean = (v) => (v === undefined || v === null) ? null : String(v).replace(/^=/, "").trim();

const topic = clean(parsedData.topic);
const postType = (clean(parsedData.post_type) || "").toLowerCase();

// Normalize the image intent from BOTH supported shapes:
//  - generate_image: true/"true"
//  - post_type: "image"
const generateImage =
  parsedData.generate_image === true ||
  parsedData.generate_image === "true" ||
  postType === "image";

return [{
  json: {
    user_id: parsedData.user_id || null,
    post_content: parsedData.post_content || null,
    image_url: parsedData.image_url || null,
    publish_now: parsedData.publish_now,
    topic: topic || null,
    post_type: postType || (generateImage ? "image" : "text"),
    posts_per_day: parsedData.posts_per_day || null,
    generate_image: generateImage,
    raw_payload: parsedData
  }
}];

const webhookData = $('Parse Webhook Payload').item.json;
const settings = $input.first()?.json || {};

const activeTopic = webhookData.topic || settings.topic || '"Artificial Intelligence" OR "DevOps"';

return [{
  json: {
    selected_topic: activeTopic,
    search_query: activeTopic
  }
}];

