// --- Determine which route this execution took ---
const parsed = $('Parse Webhook Payload').item.json;
const isImagePost = parsed.generate_image === true;

// --- Safely resolve the image reference ONLY if the image route ran ---
// Referencing an unexecuted node throws, so guard with try/catch and the route flag.
let imageUrl = null;
if (isImagePost) {
  try {
    imageUrl = $('Register Upload').item.json.value.asset || null; // LinkedIn media URN
  } catch (e) {
    imageUrl = null;
  }
}

const llmOutput = $('Basic LLM Chain').item.json.output?.post_text;
const topic = $('Select Manual Topic').item.json.selected_topic;
const item0 = ($('Edit Fields').item.json.rss?.channel?.item?.[0]) || {};
const linkedinResponse = $input.first()?.json || {};

return [{
  json: {
    user_id: parsed.user_id || "default-user",
    post_text: llmOutput || "Automated LinkedIn Post",
    topic_used: topic || null,
    article_headline: item0.title || null,
    article_url: item0.link || null,
    linkedin_post_id: linkedinResponse.id || null,
    // image_url: media URN on the image route, explicit null on the text route
    image_url: imageUrl,
    published_at: new Date().toISOString()
  }
}];

