  return [{
    json: {
      target: 'page',
      node_id: fb.page_id || null,
      token: fb.page_access_token || null
    }
  }];
}

return [{
  json: {
    target: 'profile',
    node_id: fb.facebook_user_id || 'me',
    token: fb.access_token || null
  }
}];

